<?php
declare(strict_types=1);namespace app\common\service\storage\driver;
use app\common\service\storage\StorageDriver;use app\common\service\storage\StoragePath;
final readonly class LocalStorageDriver implements StorageDriver
{private string $root;public function __construct(private array $space){$r=(string)($space['local_path']??'');if(!in_array($r,['public/storage','private/storage'],true))throw new \RuntimeException('本地存储空间配置无效');$this->root=rtrim(app()->getRootPath(),DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$r);}public function put(string $k,string $p):void{$t=$this->path($k);$d=dirname($t);$m=$this->space['access_type']==='private'?0700:0755;if((!is_dir($d)&&!mkdir($d,$m,true))||!copy($p,$t))throw new \RuntimeException('本地文件写入失败');@chmod($t,$this->space['access_type']==='private'?0600:0644);}public function delete(string $k):void{$p=$this->path($k);if(is_file($p)&&!unlink($p))throw new \RuntimeException('本地文件删除失败');}public function publicUrl(string $k):string{if($this->space['access_type']!=='public')throw new \RuntimeException('私有文件不能生成公开地址');return rtrim((string)request()->domain(),'/').'/storage/'.StoragePath::assertObjectKey($k);}public function temporaryUrl(string $k,int $e,string $f,string $d):string{throw new \RuntimeException('本地私有文件使用内部交付');}public function localPath(string $k):?string{return$this->path($k);}private function path(string $k):string{return$this->root.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,StoragePath::assertObjectKey($k));}}
